def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[-1][1] == 'D' else 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_def = sum(1 for x in opp if x == 'D')
    my_def = sum(1 for x in my if x == 'D')
    last_opp = opp[-1]
    last_my = my[-1]

    opp_def_streak = 0
    for x in reversed(opp):
        if x == 'D':
            opp_def_streak += 1
        else:
            break

    ret_count = 0
    my_def_before = 0
    for i in range(n - 1):
        if my[i] == 'D':
            my_def_before += 1
            if opp[i + 1] == 'D':
                ret_count += 1
    ret_rate = ret_count / my_def_before if my_def_before > 0 else 0.0

    exploit = (my_def >= 3 and ret_rate < 0.5) or (opp_def == 0 and my_def > 0)

    if n >= 98:
        return 'D'

    if opp_def == 0:
        if n == 2:
            return 'D'
        if n == 3:
            return 'C'
        if n == 4:
            return 'C' if last_opp == 'D' else 'D'
        if my_def == 0:
            if n >= 5 and n % 7 == 0:
                return 'D'
            return 'C'
        else:
            return 'D'

    if exploit:
        return 'D'

    if opp_def == n:
        return 'D'

    if opp_def_streak >= 5:
        return 'D'

    if last_opp == 'D':
        if opp_def_streak >= 2:
            if last_my == 'D':
                if opp_def < n:
                    if opp_def_streak >= 4:
                        return 'C' if rng.random() < 0.6 else 'D'
                    else:
                        return 'C' if rng.random() < 0.3 else 'D'
                else:
                    return 'D'
            else:
                return 'D'
        else:
            if last_my == 'D':
                return 'C'
            else:
                if opp_def >= 3 and opp_def * 2 >= n:
                    return 'D'
                return 'C'
    else:
        if last_my == 'D':
            if ret_rate >= 0.7:
                return 'C'
            else:
                return 'D'
        else:
            if my_def > 0 and ret_rate < 0.7 and n >= 5:
                all_cc = True
                for i in range(max(0, n - 5), n):
                    if my[i] != 'C' or opp[i] != 'C':
                        all_cc = False
                        break
                if all_cc and rng.random() < 0.2:
                    return 'D'
            return 'C'
